public class Main {
    static class Account {
        private double balance;

        Account(double opening) {
            if (opening < 0) throw new IllegalArgumentException("opening must be >= 0");
            this.balance = opening;
        }

        void deposit(double amount) {
            if (amount <= 0) return;
            balance += amount;
        }

        boolean withdraw(double amount) {
            if (amount <= 0 || amount > balance) return false;
            balance -= amount;
            return true;
        }

        double getBalance() { return balance; }
    }

    public static void main(String[] args) {
        Account acc = new Account(100);
        acc.deposit(50);
        System.out.println(acc.withdraw(200));
        System.out.println(acc.withdraw(120));
        System.out.printf("%.2f%n", acc.getBalance());
    }
}

public class Main {
    static class Employee {
        private static int created = 0;
        private final int id;
        private final String name;

        Employee(String name) {
            this.name = name;
            this.id = ++created;
        }

        String label() { return "#" + id + " " + name; }
    }

    public static void main(String[] args) {
        Employee a = new Employee("Aman");
        Employee b = new Employee("Priya");
        System.out.println(a.label());
        System.out.println(b.label());
        System.out.println(Employee.created);
    }
}

